import { useState } from "react";

type SmoothImageProps = {
  src: string;
  alt: string;
};

const SmoothImage = ({ src, alt }: SmoothImageProps) => {
  const [loaded, setLoaded] = useState(false);

  // Replace `-min.jpg` or `.jpg` with `-lowres.jpg`
  const lowResSrc = src.includes("-min")
    ? src.replace("-min", "-lowres")
    : src.replace(/(\.jpg|\.png)$/, "-lowres$1");

  return (
    <div style={{ position: "relative", overflow: "hidden" }}>
      {/* Low-res blurred preview */}
      <img
        src={lowResSrc}
        alt=""
        aria-hidden="true"
        style={{
          width: "100%",
          height: "auto",
          filter: "blur(20px)",
          position: "absolute",
          top: 0,
          left: 0,
          transition: "opacity 0.4s ease",
          opacity: loaded ? 0 : 1,
        }}
      />
      {/* Full-resolution image */}
      <img
        src={src}
        alt={alt}
        loading="lazy"
        onLoad={() => setLoaded(true)}
        style={{
          width: "100%",
          height: "auto",
          transition: "opacity 0.6s ease",
          opacity: loaded ? 1 : 0,
        }}
      />
    </div>
  );
};

export default SmoothImage;
